use super::parse::{parse_authority, parse_path_query_fragment, split_scheme_and_authority};

#[derive(Clone, Debug, Default, Eq, PartialEq)]
pub struct URL {
    scheme: String,
    userinfo: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    pub fn new(input: impl Into<String>) -> Self {
        let input = input.into();
        let (scheme, authority_input, remainder) = split_scheme_and_authority(&input);
        let (userinfo, host, port) = authority_input
            .map(parse_authority)
            .unwrap_or_else(|| (String::new(), String::new(), -1));
        let (path, query, fragment) = parse_path_query_fragment(remainder);

        Self {
            scheme,
            userinfo,
            host,
            port,
            path,
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> String {
        let mut authority = String::new();

        if !self.userinfo.is_empty() {
            authority.push_str(&self.userinfo);
            authority.push('@');
        }

        authority.push_str(&self.host);

        if self.port != -1 {
            authority.push(':');
            authority.push_str(&self.port.to_string());
        }

        authority
    }

    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme.is_empty()
    }

    pub fn has_authority(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.port != -1
    }

    pub fn has_path(&self) -> bool {
        !self.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.fragment.is_empty()
    }

    pub fn to_string(&self) -> String {
        let mut output = String::new();

        if self.has_scheme() {
            output.push_str(&self.scheme);
            output.push_str("://");
            output.push_str(&self.authority());
        }

        output.push_str(&self.path);

        if self.has_query() {
            output.push('?');
            output.push_str(&self.query);
        }

        if self.has_fragment() {
            output.push('#');
            output.push_str(&self.fragment);
        }

        output
    }

    pub fn is_valid(&self) -> bool {
        self.has_host() || self.has_path()
    }
}

#[cfg(test)]
mod tests {
    use super::URL;

    #[test]
    fn matches_reference_examples() {
        let url = URL::new("http://user:pass@host:123/path?x#y");
        assert_eq!(url.scheme(), "http");
        assert_eq!(url.authority(), "user:pass@host:123");
        assert_eq!(url.userinfo(), "user:pass");
        assert_eq!(url.host(), "host");
        assert_eq!(url.port(), 123);
        assert_eq!(url.path(), "/path");
        assert_eq!(url.query(), "x");
        assert_eq!(url.fragment(), "y");
        assert!(url.has_scheme());
        assert!(url.has_authority());
        assert!(url.has_userinfo());
        assert!(url.has_host());
        assert!(url.has_port());
        assert!(url.has_path());
        assert!(url.has_query());
        assert!(url.has_fragment());
        assert_eq!(url.to_string(), "http://user:pass@host:123/path?x#y");
        assert!(url.is_valid());
    }

    #[test]
    fn drops_empty_authority_from_string_without_scheme() {
        let url = URL::new("://host/path?x#f");
        assert_eq!(url.authority(), "host");
        assert_eq!(url.to_string(), "/path?x#f");
        assert!(url.is_valid());
    }
}

