pub fn split_scheme_and_authority(input: &str) -> (String, Option<&str>, &str) {
    if let Some(pos) = input.find("://") {
        let scheme = input[..pos].to_string();
        let rest = &input[(pos + 3)..];

        if let Some(split_at) = rest.find(['/', '?', '#']) {
            (scheme, Some(&rest[..split_at]), &rest[split_at..])
        } else {
            (scheme, Some(rest), "")
        }
    } else {
        (String::new(), None, input)
    }
}

pub fn parse_authority(input: &str) -> (String, String, i32) {
    let mut userinfo = String::new();
    let mut host_and_port = input;

    if let Some(at_pos) = input.find('@') {
        let candidate = &input[..at_pos];
        if !candidate.is_empty() {
            userinfo = candidate.to_string();
        }
        host_and_port = &input[(at_pos + 1)..];
    }

    if let Some(colon_pos) = host_and_port.find(':') {
        let host = host_and_port[..colon_pos].to_string();
        let port = parse_port(&host_and_port[(colon_pos + 1)..]).unwrap_or(-1);
        (userinfo, host, port)
    } else {
        (userinfo, host_and_port.to_string(), -1)
    }
}

pub fn parse_path_query_fragment(input: &str) -> (String, String, String) {
    match (input.find('?'), input.find('#')) {
        (Some(query_pos), Some(fragment_pos)) if query_pos < fragment_pos => (
            input[..query_pos].to_string(),
            input[(query_pos + 1)..fragment_pos].to_string(),
            input[(fragment_pos + 1)..].to_string(),
        ),
        (_, Some(fragment_pos)) => (
            input[..fragment_pos].to_string(),
            String::new(),
            input[(fragment_pos + 1)..].to_string(),
        ),
        (Some(query_pos), None) => (
            input[..query_pos].to_string(),
            input[(query_pos + 1)..].to_string(),
            String::new(),
        ),
        (None, None) => (input.to_string(), String::new(), String::new()),
    }
}

fn parse_port(input: &str) -> Option<i32> {
    if input.is_empty() {
        return None;
    }

    let bytes = input.as_bytes();
    let mut index = 0usize;
    let mut negative = false;

    match bytes[0] {
        b'+' => {
            index = 1;
        }
        b'-' => {
            negative = true;
            index = 1;
        }
        _ => {}
    }

    let digit_start = index;
    let mut value: i64 = 0;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        value = (value * 10) + i64::from(bytes[index] - b'0');
        index += 1;
    }

    if index == digit_start {
        return None;
    }

    let signed_value = if negative { -value } else { value };
    if (0..=65535).contains(&signed_value) {
        Some(signed_value as i32)
    } else {
        None
    }
}
